module RoundingUnit(
  input  [22:0] io_in,
  input         io_roundIn,
                io_stickyIn,
                io_signIn,
  input  [2:0]  io_rm,
  output [22:0] io_out,
  output        io_inexact,
                io_cout
);

  wire inexact = io_roundIn | io_stickyIn;
  wire r_up =
    io_rm == 3'h4
      ? io_roundIn
      : io_rm == 3'h2
          ? inexact & io_signIn
          : io_rm == 3'h3
              ? inexact & ~io_signIn
              : io_rm != 3'h1 & io_rm == 3'h0
                & (io_roundIn & io_stickyIn | io_roundIn & ~io_stickyIn & io_in[0]);
  assign io_out = r_up ? io_in + 23'h1 : io_in;
  assign io_inexact = inexact;
  assign io_cout = r_up & (&io_in);
endmodule

module TininessRounder(
  input         io_in_sign,
  input  [26:0] io_in_sig,
  input  [2:0]  io_rm,
  output        io_tininess
);

  wire _rounder_io_cout;
  RoundingUnit rounder (
    .io_in       (io_in_sig[24:2]),
    .io_roundIn  (io_in_sig[1]),
    .io_stickyIn (io_in_sig[0]),
    .io_signIn   (io_in_sign),
    .io_rm       (io_rm),
    .io_out      (/* unused */),
    .io_inexact  (/* unused */),
    .io_cout     (_rounder_io_cout)
  );
  assign io_tininess =
    io_in_sig[26:25] == 2'h0 | io_in_sig[26:25] == 2'h1 & ~_rounder_io_cout;
endmodule

module NormAlignFP16INTInner(
  input         clock,
                reset,
  output        io_in_ready,
  input         io_in_valid,
  input  [19:0] io_in_bits_sigSigned,
  input  [5:0]  io_in_bits_baseExp,
  input  [2:0]  io_in_bits_rm,
  input         io_out_ready,
  output        io_out_valid,
  output [31:0] io_out_bits_result
);

  wire        s1_ready;
  wire [22:0] _rounder_io_out;
  wire        _rounder_io_cout;
  reg         s0Pipe_rValid;
  reg         s0Pipe_rBits_sign;
  reg  [2:0]  s0Pipe_rBits_rm;
  reg  [7:0]  s0Pipe_rBits_exp;
  reg  [18:0] s0Pipe_rBits_sig;
  wire        s0_ready = ~s0Pipe_rValid | s1_ready;
  reg         io_out_rValid;
  reg  [31:0] io_out_rBits_result;
  assign s1_ready = ~io_out_rValid | io_out_ready;
  always @(posedge clock) begin
    automatic logic _s0Pipe_T;
    automatic logic _io_out_T;
    _s0Pipe_T = s0_ready & io_in_valid;
    _io_out_T = s1_ready & s0Pipe_rValid;
    if (reset) begin
      s0Pipe_rValid <= 1'h0;
      io_out_rValid <= 1'h0;
    end
    else begin
      s0Pipe_rValid <= _s0Pipe_T | ~(s1_ready & s0Pipe_rValid) & s0Pipe_rValid;
      io_out_rValid <= _io_out_T | ~(io_out_ready & io_out_rValid) & io_out_rValid;
    end
    if (_s0Pipe_T) begin
      automatic logic [19:0] sig =
        io_in_bits_sigSigned[19] ? ~io_in_bits_sigSigned + 20'h1 : io_in_bits_sigSigned;
      automatic logic [4:0]  lzCount =
        sig[18]
          ? 5'h0
          : sig[17]
              ? 5'h1
              : sig[16]
                  ? 5'h2
                  : sig[15]
                      ? 5'h3
                      : sig[14]
                          ? 5'h4
                          : sig[13]
                              ? 5'h5
                              : sig[12]
                                  ? 5'h6
                                  : sig[11]
                                      ? 5'h7
                                      : sig[10]
                                          ? 5'h8
                                          : sig[9]
                                              ? 5'h9
                                              : sig[8]
                                                  ? 5'hA
                                                  : sig[7]
                                                      ? 5'hB
                                                      : sig[6]
                                                          ? 5'hC
                                                          : sig[5]
                                                              ? 5'hD
                                                              : sig[4]
                                                                  ? 5'hE
                                                                  : sig[3]
                                                                      ? 5'hF
                                                                      : sig[2]
                                                                          ? 5'h10
                                                                          : sig[1]
                                                                              ? 5'h11
                                                                              : {4'h9,
                                                                                 ~(sig[0])};
      automatic logic [50:0] shifted = {31'h0, sig} << lzCount;
      s0Pipe_rBits_sign <= io_in_bits_sigSigned[19];
      s0Pipe_rBits_rm <= io_in_bits_rm;
      s0Pipe_rBits_exp <= {2'h0, io_in_bits_baseExp - {1'h0, lzCount}} + 8'h7C;
      s0Pipe_rBits_sig <= shifted[18:0];
    end
    if (_io_out_T) begin
      automatic logic commonOf =
        _rounder_io_cout ? s0Pipe_rBits_exp == 8'hFE : (&s0Pipe_rBits_exp);
      automatic logic rmin =
        s0Pipe_rBits_rm == 3'h1 | s0Pipe_rBits_rm == 3'h2 & ~s0Pipe_rBits_sign
        | s0Pipe_rBits_rm == 3'h3 & s0Pipe_rBits_sign;
      io_out_rBits_result <=
        {s0Pipe_rBits_sign,
         commonOf ? {7'h7F, ~rmin} : s0Pipe_rBits_exp + {7'h0, _rounder_io_cout},
         commonOf ? {23{rmin}} : _rounder_io_out};
    end
  end // always @(posedge)
  TininessRounder tininessRounder (
    .io_in_sign  (s0Pipe_rBits_sign),
    .io_in_sig   ({{8{s0Pipe_rBits_sig[18]}}, s0Pipe_rBits_sig}),
    .io_rm       (s0Pipe_rBits_rm),
    .io_tininess (/* unused */)
  );
  RoundingUnit rounder (
    .io_in       ({{7{s0Pipe_rBits_sig[18]}}, s0Pipe_rBits_sig[18:3]}),
    .io_roundIn  (s0Pipe_rBits_sig[2]),
    .io_stickyIn (|(s0Pipe_rBits_sig[1:0])),
    .io_signIn   (s0Pipe_rBits_sign),
    .io_rm       (s0Pipe_rBits_rm),
    .io_out      (_rounder_io_out),
    .io_inexact  (/* unused */),
    .io_cout     (_rounder_io_cout)
  );
  assign io_in_ready = s0_ready;
  assign io_out_valid = io_out_rValid;
  assign io_out_bits_result = io_out_rBits_result;
endmodule

